	private static final Set<String> STOP_REASONS = Set.of("HIGH_CONFIDENCE", "DETERMINISTIC_FINDING",
		"NO_MORE_MEASUREMENTS", "MAX_STEPS", "USER_STOP");
	private static final Set<String> LEARNING_SYSTEMS = Set.of(
		"ANALOG_ADC", "DIGITAL_INPUT", "LED_GPIO", "I2C_SENSOR", "UART_DEVICE", "PWM_MOTOR_SERVO");

	private static String eligibleLearningArticleBody(IContext caller, String system) {
		if (!LEARNING_SYSTEMS.contains(system)) return "";
		try {
			List<IMendixObject> resources = Core.createXPathQuery(
				"//MyFirstModule.Resource[ContentKey = $key and IsActive = true()"
				+ " and ArticleBody != '' and LicenseName != '' and Attribution != '' and SourceURL != ''"
				+ "]")
				.setVariable("key", system).setAmount(2).execute(caller);
			if (resources.size() != 1) return "";
			IMendixObject resource = resources.get(0);
			for (String member : List.of("ArticleBody", "LicenseName", "Attribution", "SourceURL")) {
				Object value = resource.getValue(caller, member);
				if (!(value instanceof String text) || text.isBlank()) return "";
			}
			return resource.getValue(caller, "ArticleBody");
		} catch (Exception unavailable) {
			logger().warn("Current learning source is unavailable; no verified section will be suggested.");
			return "";
		}
	}
	private static final Map<String, String> KNOWLEDGE_TOPICS = Map.of(
		"COMPONENT_TESTING", "Component Testing", "DATASHEET_BASICS", "Reading Datasheets",
		"NOISE", "Electrical Noise", "SIGNAL_INTEGRITY", "Signal Integrity",
		"GROUNDING", "Grounding");
	private static final Map<String, String> KNOWLEDGE_DESCRIPTIONS = Map.of(
		"COMPONENT_TESTING", "Learn how to check a component's operation.",
		"DATASHEET_BASICS", "Find the specifications needed for troubleshooting.",
		"NOISE", "Learn how electrical noise affects measurements.",
		"SIGNAL_INTEGRITY", "Learn how distorted signals affect circuit behavior.",
		"GROUNDING", "Learn how the voltage reference affects accuracy.");

	private record FaultData(String code, BigDecimal probability) {}
	private record RuleData(String code, String fault, String severity, String message) {}
	private record GuidanceData(String title, String summary, String quantity, String point,
		String reference, List<String> tools, String why, List<String> steps,
		List<String> formulas, List<String> plainFormulas, String formulaCaption,
		String formulaNote, String safety, String inputPrompt, String inputHint) {}
	private record QuestionData(String code, String text, String type, String unit, GuidanceData guidance) {}
	private record KnowledgeData(String code, String name) {}
	private record ResponseData(String systemType, BigDecimal confidence, boolean complete, String stopReason,
		List<FaultData> faults, List<RuleData> rules, QuestionData question, List<KnowledgeData> knowledge) {}

	private List<IMendixObject> sessionChildren(IContext context, IMendixObject session, String entity, String association) {
		return Core.createXPathQuery("//" + entity + "[" + association + " = $session]")
			.setVariable("session", session.getId()).execute(context);
	}

	private List<IMendixObject> questionChildren(IContext context, String entity, String association, IMendixObject question) {
		return Core.createXPathQuery("//" + entity + "[" + association + " = $question]")
			.setVariable("question", question.getId()).execute(context);
	}

	private static IMendixObject resolveTopic(IContext context, String code) {
		String title = KNOWLEDGE_TOPICS.get(code);
		if (title == null) {
			return null;
		}
		List<IMendixObject> topics = Core.createXPathQuery(
			"//MyFirstModule.Topic[Name = $title and IsActive = true()]")
			.setVariable("title", title).execute(context);
		return topics.size() == 1 ? topics.get(0) : null;
	}

	private static void setQuestionGuidance(IContext context, DiagnosticQuestion question, GuidanceData guidance) {
		IMendixObject object = question.getMendixObject();
		object.setValue(context, "DisplayTitle", guidance.title());
		object.setValue(context, "Summary", guidance.summary());
		object.setValue(context, "Quantity", guidance.quantity());
		object.setValue(context, "MeasurementPoint", guidance.point());
		object.setValue(context, "ReferencePoint", guidance.reference());
		object.setValue(context, "ToolText", String.join(" OR ", guidance.tools()));
		object.setValue(context, "WhyText", guidance.why());
		object.setValue(context, "SafetyText", guidance.safety());
		object.setValue(context, "FormulaCaption", guidance.formulaCaption());
		object.setValue(context, "FormulaNote", guidance.formulaNote());
		object.setValue(context, "InputPrompt", guidance.inputPrompt());
		object.setValue(context, "InputHint", guidance.inputHint());
	}

	private static ResponseData parseResponse(String rawJson) throws Exception {
		if (rawJson == null || rawJson.isBlank()) {
			throw new IllegalArgumentException("The response body is empty");
		}
		JSONTokener tokener = new JSONTokener(rawJson);
		Object value = tokener.nextValue();
		if (!(value instanceof JSONObject root) || tokener.nextClean() != 0) {
			throw new IllegalArgumentException("Expected one JSON response object");
		}
		String systemType = requiredString(root, "system_type");
		BigDecimal confidence = probability(root, "confidence");
		Object completed = root.get("diagnosis_complete");
		if (!(completed instanceof Boolean complete)) {
			throw new IllegalArgumentException("diagnosis_complete must be a non-null Boolean");
		}
		String stopReason = nullableString(root, "stop_reason");
		if (!stopReason.isEmpty() && !STOP_REASONS.contains(stopReason)) {
			throw new IllegalArgumentException("Unsupported stop_reason");
		}

		List<FaultData> faults = new ArrayList<>();
		JSONArray diagnosis = requiredArray(root, "diagnosis");
		for (int i = 0; i < diagnosis.length(); i++) {
			JSONObject fault = diagnosis.getJSONObject(i);
			faults.add(new FaultData(requiredString(fault, "fault"), probability(fault, "probability")));
		}
		List<RuleData> rules = new ArrayList<>();
		JSONArray findings = requiredArray(root, "rule_findings");
		for (int i = 0; i < findings.length(); i++) {
			JSONObject rule = findings.getJSONObject(i);
			String severity = requiredString(rule, "severity");
			if (!Set.of("info", "warning", "critical").contains(severity)) {
				throw new IllegalArgumentException("Unsupported rule severity");
			}
			rules.add(new RuleData(requiredString(rule, "rule_id"), requiredString(rule, "fault"),
				severity, requiredString(rule, "message")));
		}
		QuestionData question = null;
		Object next = root.opt("next_measurement");
		if (next != null && next != JSONObject.NULL) {
			if (!(next instanceof JSONObject item)) {
				throw new IllegalArgumentException("next_measurement must be an object or null");
			}
			String type = requiredString(item, "type");
			if (!Set.of("numeric", "boolean", "choice").contains(type)) {
				throw new IllegalArgumentException("Unsupported next_measurement type");
			}
			BigDecimal gain = number(item, "information_gain");
			if (gain.signum() < 0) {
				throw new IllegalArgumentException("information_gain must be nonnegative");
			}
			// The current DiagnosticQuestion entity has no InformationGain attribute.
			question = new QuestionData(requiredString(item, "id"), requiredString(item, "question"),
				type, nullableString(item, "unit"), optionalGuidance(item));
		}
		List<KnowledgeData> knowledge = new ArrayList<>();
		JSONArray recommendations = requiredArray(root, "recommended_knowledge");
		for (int i = 0; i < recommendations.length(); i++) {
			JSONObject item = recommendations.getJSONObject(i);
			knowledge.add(new KnowledgeData(requiredString(item, "knowledge_code"), requiredString(item, "name")));
		}
		return new ResponseData(systemType, confidence, complete, stopReason, List.copyOf(faults),
			List.copyOf(rules), question, List.copyOf(knowledge));
	}

	private static String requiredString(JSONObject object, String field) throws Exception {
		Object value = object.get(field);
		if (!(value instanceof String text) || text.isBlank()) {
			throw new IllegalArgumentException(field + " must be a nonempty String");
		}
		return text;
	}

	private static String nullableString(JSONObject object, String field) throws Exception {
		Object value = object.opt(field);
		if (value == null || value == JSONObject.NULL) {
			return "";
		}
		if (!(value instanceof String text)) {
			throw new IllegalArgumentException(field + " must be a String or null");
		}
		return text;
	}

	private static List<String> optionalStrings(JSONObject object, String field) throws Exception {
		Object value = object.opt(field);
		if (value == null || value == JSONObject.NULL) {
			return List.of();
		}
		if (!(value instanceof JSONArray array)) {
			throw new IllegalArgumentException(field + " must be an array or null");
		}
		List<String> result = new ArrayList<>();
		for (int i = 0; i < array.length(); i++) {
			Object item = array.get(i);
			if (!(item instanceof String text) || text.isBlank()) {
				throw new IllegalArgumentException(field + " must contain nonempty Strings");
			}
			result.add(text);
		}
		return List.copyOf(result);
	}

	private static GuidanceData optionalGuidance(JSONObject question) throws Exception {
		Object value = question.opt("guidance");
		if (value == null || value == JSONObject.NULL) {
			return null;
		}
		if (!(value instanceof JSONObject guidance)) {
			throw new IllegalArgumentException("guidance must be an object or null");
		}
		List<String> formulas = optionalStrings(guidance, "formula_latex");
		List<String> plain = optionalStrings(guidance, "formula_plain");
		if (!plain.isEmpty() && plain.size() != formulas.size()) {
			throw new IllegalArgumentException("formula_plain must match formula_latex");
		}
		return new GuidanceData(nullableString(guidance, "title"), nullableString(guidance, "summary"),
			nullableString(guidance, "quantity"), nullableString(guidance, "measurement_point"),
			nullableString(guidance, "reference_point"), optionalStrings(guidance, "recommended_tools"),
			nullableString(guidance, "why"), optionalStrings(guidance, "steps"), formulas, plain,
			nullableString(guidance, "formula_caption"), nullableString(guidance, "formula_note"),
			nullableString(guidance, "safety_note"), nullableString(guidance, "input_prompt"),
			nullableString(guidance, "input_hint"));
	}

	private static JSONArray requiredArray(JSONObject object, String field) throws Exception {
		Object value = object.get(field);
		if (!(value instanceof JSONArray array)) {
			throw new IllegalArgumentException(field + " must be an array (empty is allowed)");
		}
		return array;
	}

	private static BigDecimal number(JSONObject object, String field) throws Exception {
		Object value = object.get(field);
		if (!(value instanceof Number numeric) || !Double.isFinite(numeric.doubleValue())) {
			throw new IllegalArgumentException(field + " must be a finite number");
		}
		return new BigDecimal(numeric.toString());
	}

	private static BigDecimal probability(JSONObject object, String field) throws Exception {
		BigDecimal value = number(object, field);
		if (value.signum() < 0 || value.compareTo(BigDecimal.ONE) > 0) {
			throw new IllegalArgumentException(field + " must be between 0 and 1");
		}
		return value;
	}

	private static String readableName(String code) {
		return code.replace('_', ' ').replaceAll("([a-z])([A-Z])", "$1 $2");
	}
